func restoreCiscoAsr9902Components(t *testing.T, cur map[[2]string]string) {
	t.Helper()
	reverseProfileEdits(t, cur, ciscoAsr9902Profile, "cisco_asr9902 components", ciscoAsr9902ComponentsEdits)
}

func ciscoAsr9902ComponentsOIDNamesBefore(t *testing.T, names []string) []string {
	t.Helper()
	return reverseOIDNameEdits(t, names, "cisco_asr9902 components", ciscoAsr9902ComponentsAddedOIDNames, ciscoAsr9902ComponentsRemovedOIDNames)
}

func TestCiscoAsr9902ComponentsReproduceTheParentCorpus(t *testing.T) {
	if got := corpusTagDigestAt(t, corpusValuesAt(t, ciscoAsr9902ComponentsParentRevision), ciscoAsr9902ComponentsParentRevision); got != shippedTagDigestBeforeCiscoAsr9902Components {
		t.Errorf("reversing the components change gives digest %s, want %s: another shipped row changed without being recorded",
			got, shippedTagDigestBeforeCiscoAsr9902Components)
	}
}

func TestCiscoAsr9902ComponentsRePinIsOnlyTheEdit(t *testing.T) {
	restored := restoreCorpusOIDNamesTo(t, collectShippedOIDs(t), ciscoAsr9902ComponentsParentRevision)
	if got := corpusOIDNameDigest(restored); got != shippedOIDEncodingDigestBeforeCiscoAsr9902Components {
		t.Errorf("reversing the components OID names gives digest %s, want %s", got, shippedOIDEncodingDigestBeforeCiscoAsr9902Components)
	}
}
